# 时序图：自动识别日期列，按类别与最小时间单位汇总数值
import io
import re
import base64
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates

plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.sans-serif': ['Microsoft YaHei', 'SimHei', 'Arial', 'DejaVu Sans'],
    'axes.unicode_minus': False,
    'font.size': 10,
    'axes.titlesize': 15,
    'axes.labelsize': 11,
    'xtick.labelsize': 9,
    'ytick.labelsize': 9,
    'legend.fontsize': 9,
    'figure.facecolor': 'white',
    'axes.facecolor': 'white',
    'savefig.facecolor': 'white',
    'savefig.dpi': 300,
})

PALETTE = ['#4F7FB3', '#DD6F75', '#956CB4', '#57A36B', '#DF9A3C', '#3E9CA6']
GRID = '#D9DEE5'
TEXT = '#2D333B'
category_column = {{category_column}}
value_column = {{value_column}}
time_range = {{time_range}}
minimum_unit = {{minimum_unit}}
use_smoothing = bool({{smoothing}})
keep_scatter = bool({{keep_scatter}})


def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


def _normalise_date_text(value):
    if pd.isna(value):
        return None
    text = str(value).strip()
    if not text:
        return None
    text = text.replace('年', '-').replace('月', '-').replace('日', '')
    month_only = re.fullmatch(r'(\d{4})[.\-/](\d{1,2})[.\-/]?', text)
    if month_only:
        return f'{month_only.group(1)}-{int(month_only.group(2)):02d}-01'
    full_date = re.fullmatch(r'(\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})(.*)', text)
    if full_date:
        return f'{full_date.group(1)}-{int(full_date.group(2)):02d}-{int(full_date.group(3)):02d}{full_date.group(4)}'
    return text


def _parse_dates(series):
    normalised = series.map(_normalise_date_text)
    try:
        return pd.to_datetime(normalised, errors='coerce', format='mixed')
    except (TypeError, ValueError):
        return pd.to_datetime(normalised, errors='coerce')


def _detect_date_column(frame, excluded):
    keywords = ('时间', '日期', '年月', '月份', 'date', 'time', 'timestamp')
    candidates = []
    for index, column in enumerate(frame.columns):
        if column in excluded:
            continue
        name = str(column).lower()
        named = any(word in name for word in keywords)
        if pd.api.types.is_numeric_dtype(frame[column]) and not named:
            continue
        parsed = _parse_dates(frame[column])
        valid = int(parsed.notna().sum())
        if valid == 0:
            continue
        ratio = valid / max(1, len(frame))
        score = ratio + (2.0 if named else 0.0) - index * 1e-6
        candidates.append((score, column, parsed))
    if not candidates:
        raise RuntimeError('没有自动识别到日期列；请把日期列命名为“日期”“时间”“date”等，并使用可识别的日期格式')
    candidates.sort(key=lambda item: item[0], reverse=True)
    score, column, parsed = candidates[0]
    if score < 0.6:
        raise RuntimeError('日期列有效日期不足 60%，请检查日期格式')
    return column, parsed


def _parse_time_range(raw):
    text = '' if raw is None else str(raw).strip()
    if not text:
        return None, None, '全部时间'
    endpoint_pattern = r'\d{4}(?:\.\d{1,2}(?:\.\d{1,2})?)?'
    match = re.fullmatch(rf'({endpoint_pattern})(?:\s*-\s*({endpoint_pattern}))?', text)
    if not match:
        raise RuntimeError('时间段格式不正确：支持 2020、2020.3、2020.3.4，或用“-”连接两个日期')

    def endpoint_bounds(value):
        parts = [int(part) for part in value.split('.')]
        year = parts[0]
        month = parts[1] if len(parts) >= 2 else 1
        day = parts[2] if len(parts) == 3 else 1
        if len(parts) >= 2 and not 1 <= month <= 12:
            raise RuntimeError('月份必须在 1 到 12 之间，例如 2020.3')
        try:
            start_at = pd.Timestamp(year=year, month=month, day=day)
        except ValueError as error:
            raise RuntimeError(f'日期不存在：{value}') from error
        if len(parts) == 1:
            end_at = start_at + pd.offsets.YearBegin(1)
        elif len(parts) == 2:
            end_at = start_at + pd.offsets.MonthBegin(1)
        else:
            end_at = start_at + pd.Timedelta(days=1)
        return start_at, end_at

    start_text = match.group(1)
    end_text = match.group(2)
    start, single_end = endpoint_bounds(start_text)
    if end_text is None:
        return start, single_end, start_text
    end_start, end_exclusive = endpoint_bounds(end_text)
    if end_start < start:
        raise RuntimeError('时间段的结束日期不能早于开始日期')
    return start, end_exclusive, f'{start_text}-{end_text}'


def _bucket_dates(dates, unit):
    if unit == '小时':
        return dates.dt.floor('h')
    if unit == '日':
        return dates.dt.floor('D')
    if unit == '周':
        return dates.dt.to_period('W-SUN').dt.start_time
    if unit == '月':
        return dates.dt.to_period('M').dt.start_time
    if unit == '年':
        return dates.dt.to_period('Y').dt.start_time
    raise RuntimeError('最小单位只能选择：小时、日、周、月或年')


if data is None:
    raise RuntimeError('请先连接并运行上游的数据导入插件')
df = _to_frame(data)
if df.empty:
    raise RuntimeError('CSV 是空表，没有可绘制的数据')
if category_column and category_column not in df.columns:
    raise RuntimeError('找不到类别列：' + category_column)
if not value_column or value_column not in df.columns:
    raise RuntimeError('请选择有效的时序列')
if category_column and category_column == value_column:
    raise RuntimeError('类别列和时序列不能是同一列')

excluded_columns = {value_column}
if category_column:
    excluded_columns.add(category_column)
date_column, parsed_dates = _detect_date_column(df, excluded_columns)
start, end_exclusive, range_label = _parse_time_range(time_range)
working = pd.DataFrame({
    '_date': parsed_dates,
    '_category': df[category_column] if category_column else pd.Series('全部数据', index=df.index),
    '_value': pd.to_numeric(df[value_column], errors='coerce'),
})
working = working.dropna(subset=['_date', '_category', '_value'])
working = working[working['_category'].astype(str).str.strip() != '']
if start is not None:
    working = working[(working['_date'] >= start) & (working['_date'] < end_exclusive)]
if working.empty:
    raise RuntimeError('所选时间段内没有同时具备日期、类别和数值的有效数据')

category_order = working['_category'].drop_duplicates().tolist()
if len(category_order) > 6:
    raise RuntimeError(f'所选时间段内有 {len(category_order)} 个类别，最多只能绘制 6 个类别；请先筛选或合并类别')
working['_bucket'] = _bucket_dates(working['_date'], minimum_unit)
aggregated = (
    working.groupby(['_category', '_bucket'], sort=False, observed=True)['_value']
    .sum()
    .reset_index()
    .sort_values('_bucket')
)

fig, ax = plt.subplots(figsize=(10.2, 5.8), facecolor='white')
for index, category in enumerate(category_order):
    series = aggregated[aggregated['_category'] == category].sort_values('_bucket')
    x = series['_bucket']
    raw_y = series['_value'].astype(float)
    color = PALETTE[index]
    line_y = raw_y.rolling(window=3, center=True, min_periods=1).mean() if use_smoothing else raw_y
    ax.plot(x, line_y, color=color, linewidth=2.2, label=str(category), zorder=3)
    if keep_scatter:
        ax.scatter(x, raw_y, s=27, color=color, edgecolor='white', linewidth=0.55, alpha=0.88, zorder=4)

ax.set_title(f'{value_column} 时序图', loc='left', fontweight='bold', color=TEXT, pad=13)
ax.set_xlabel(f'时间（自动识别：{date_column}；按{minimum_unit}汇总）')
ax.set_ylabel(f'{value_column}（求和）')
ax.spines['top'].set_visible(False)
ax.spines['right'].set_visible(False)
ax.spines['left'].set_color('#59636E')
ax.spines['bottom'].set_color('#59636E')
ax.grid(axis='y', linestyle='--', linewidth=0.6, color=GRID, alpha=0.72)
ax.set_axisbelow(True)
ax.xaxis.set_major_locator(mdates.AutoDateLocator(minticks=4, maxticks=10))
ax.xaxis.set_major_formatter(mdates.ConciseDateFormatter(ax.xaxis.get_major_locator()))
legend_title = str(category_column) if category_column else '类别列：不选'
ax.legend(frameon=False, loc='upper left', bbox_to_anchor=(1.01, 1.0), borderaxespad=0, title=legend_title)
mode_text = '3 点居中移动平均' if use_smoothing else '原始折线'
scatter_text = '保留原始散点' if keep_scatter else '不显示散点'
fig.text(0.075, 0.025, f'时间段：{range_label}；{mode_text}；{scatter_text}；共 {len(working):,} 条有效记录。', fontsize=8.5, color='#66707A')
fig.subplots_adjust(left=0.10, right=0.79, top=0.89, bottom=0.17)

_buffer = io.BytesIO()
fig.savefig(_buffer, format='png', dpi=300, bbox_inches=None, facecolor='white')
plt.close(fig)
image = 'data:image/png;base64,' + base64.b64encode(_buffer.getvalue()).decode('ascii')
return {'image': image}
